def nice_ces(ces):
    """Format a |CauseEffectStructure|."""
    return ' '.join(
        [nice_cause(c) for c in ces.causes] +
        [nice_effect(e) for e in ces.effects]
    )


def nice_cause(c):
    """Format a |Cause|."""
    return '{} {}'.format(nice_predicate(c.predicate), nice_arguments(c.arguments))


def nice_effect(e):
    """Format a |Effect|."""
    return '{} {}'.format(nice_predicate(e.predicate), nice_arguments(e.arguments))


def nice_predicate(p):
    """Format a |Predicate|."""
    return '{} {}'.format(p.name, nice_arguments(p.arguments))


def nice_arguments(args):
    """Format a list of |Argument|s."""
    return ' '.join([nice_argument(a) for a in args])


def nice_argument(a):
    """Format an |Argument|."""
    return '{} {}'.format(a.role, nice_value(a.value))


def nice_value(v):
    """Format a |Value|."""
    if isinstance(v, str):
        return v
    elif isinstance(v, int):
        return str(v)
    elif isinstance(v, float):
        return str(v)
    elif isinstance(v, bool):
        return 'true' if v else 'false'
    elif isinstance(v, list):
        return ' '.join([nice_value(x) for x in v])
    else:
        raise ValueError('Unknown value type: {}'.format(type(v)))


